function pair(left: ReadSpan<f64>, right: ReadSpan<f64>): f64 {
  left.length;
  return right[0];
}
export function entry(): f64 {
  const a: f64[] = [1.0];
  const v: ReadSpan<f64> = readSpan(a, 0, 1);
  const alias = v;
  return pair(v, alias);
}

